// Nimmt den KI-Text, wenn Claude geantwortet hat; sonst die gefüllte Vorlage als Fallback.
// So bleibt die Kette lauffähig, auch wenn der Key fehlt – der Entwurf ist dann sichtbar als 'vorlage' markiert.
const d = $('Vorlage + Leitplanken').item.json;
const antwort = $input.first().json;
const kiText = Array.isArray(antwort.content) ? (antwort.content.find(c => c.type === 'text')?.text ?? '') : '';
const fallback = String(d.vorlage ?? '')
  .replaceAll('[assetklasse]', d.objekt?.assetklasse ?? '')
  .replaceAll('[region]', d.objekt?.region ?? '');
const entwurf = kiText.trim() || fallback;
return [{ json: {
  entwurfId: d.entwurfId ?? ('e-' + Date.now()),
  objektId: d.objektId, investorId: d.investorId ?? null, email: d.email ?? null,
  betreff: d.betreff ?? `${d.objekt?.name ?? 'Objekt'} – vertrauliche Vorabinformation`,
  entwurf, quelle: kiText.trim() ? 'ki' : 'vorlage', kiFehler: antwort.error ? JSON.stringify(antwort.error) : null,
  status: 'wartet_auf_freigabe', erstellt: new Date().toISOString(),
} }];
